"fpkg.about": "Chỉ tới một thư mục trò chơi, hoặc ảnh gắn kết .exfat hay .ffpkg. Trình chuyển đổi đọc cây thư mục, kiểm tra có đủ mọi thứ một gói khởi chạy được cần, rồi ghi một .pkg định dạng debug vào thư mục đầu ra.",
"fpkg.aboutWhere": "Việc chuyển đổi chạy trên máy đang chạy engine — máy tính này, một máy chủ Docker hoặc thiết bị Android — không phải trên máy chơi game. Không gì tới được máy chơi game cho đến khi bạn cài gói — qua luồng từ máy tính này, hoặc tải lên PS5 trước.",
"fpkg.aboutSource": "Nguồn phải là cây trò chơi đã được giải mã. Bản cài retail không thể giải nén ở đây, và mục kiểm tra bên dưới sẽ báo nếu bạn đã chọn loại đó.",
"fpkg.aboutChecks": "Những gì được kiểm tra",
"fpkg.checkEboot": "Một eboot.bin ở gốc cây thư mục — mô-đun trò chơi. Nó phải là ELF thô hoặc SELF được bọc; mô-đun ký retail không thể đóng gói lại.",
"fpkg.checkParam": "sce_sys/param.json, và không có sce_sys/param.sfo — param.sfo sẽ đưa đường khởi chạy của máy sang lối PS4.",
"fpkg.checkIcons": "ID nội dung 36 ký tự, cả hai biểu tượng, và mô-đun quyền sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Giá trị DRM của gói là tiêu chuẩn. Giá trị miễn phí hoặc có thể nâng cấp khiến máy khóa trò chơi; nó chỉ được ghi lại trong gói, tệp của bạn không bao giờ bị động tới.",
"payloads_essentials_title": "Nên dùng cùng ps5upload",
"payloads_essentials_body": "Nếu bạn thiết lập máy lần đầu, ba payload này đáp ứng hầu hết những gì ps5upload cần: kstuff-lite (bản vá nhân mà phần lớn homebrew dựa vào), ShadowMount+ (gắn ảnh trò chơi từ bộ nhớ) và nanoDNS (giữ máy tránh đường cập nhật của Sony). Mọi thứ khác trong danh sách là tùy chọn.",
