stop: "Dừng",
activity_description_v2: "Mọi thứ ứng dụng đang làm và đã làm trên các máy console của bạn: tải lên, tải xuống, cài đặt và thao tác tệp. Dừng hoặc thử lại bất kỳ việc nào từ đây. 100 mục gần nhất được giữ lại, kể cả sau khi khởi động lại.",
fw_spoof_subtitle_v2: "Kiểm tra xem phiên bản firmware mà PS5 này báo cáo có bị một payload giả mạo thay đổi hay không, để bạn biết phiên bản thật trước khi cài thứ gì phụ thuộc vào nó.",
health_subtitle_v2: "Kiểm tra PS5, ứng dụng này và mạng giữa chúng có hoạt động không, cho bạn biết cần sửa gì nếu không, và đo tốc độ truyền tệp giữa chúng.",
remotePlay_subtitle_v2: "Thiết lập PS5 này cho Remote Play và lấy mã PIN để liên kết ứng dụng PS Remote Play với máy.",
saves_description_v2: "Dữ liệu lưu trên PS5, mỗi game một mục. Sao lưu dữ liệu lưu của một game thành tệp .zip trên máy tính này, và khôi phục sau.",
shell_description_v2: "Gõ các lệnh chạy trên PS5, bên trong tiến trình trợ giúp. Dành cho người dùng nâng cao. Đầu ra giới hạn 256 KB mỗi lệnh; mũi tên lên và xuống gọi lại các lệnh trước.",
"arcpkg.links.go": "Tải {count} tệp",
"arcpkg.links.help": "Dán liên kết trực tiếp tới tệp nén, hoặc tới từng phần của tệp nén chia nhỏ, mỗi dòng một liên kết. Các tệp được tải về máy tính này (Downloads/ps5upload), nơi cần đủ chỗ cho tất cả; sau đó các gói bên trong được giải nén lên PS5 như mô tả ở trên.",
"arcpkg.links.kept": "{count} tệp đã tải nằm trong {dir}. Chúng được giữ lại để bạn có thể thử cài lại; hãy xóa khi đã xong.",
"arcpkg.links.progress": "Đang tải tệp {n} trên {count} về máy tính này…",
"arcpkg.links.title": "Tệp nén nằm ở các liên kết tải về",
"arcpkg.noFirstPart": "Các tệp đã tải xong, nhưng không tệp nào là phần đầu của một tệp nén (.zip, .7z, .rar hoặc .part1.rar). Hãy kiểm tra các liên kết.",
"fpkg.image.done": "Ảnh đĩa game đã được ghi và đọc lại để kiểm tra. Sao chép nó vào ổ của PS5 (Tải lên) và ShadowMount+ sẽ gắn kết nó.",
"fpkg.image.what": "Một tệp bạn sao chép vào ổ PS5, ShadowMount+ sẽ gắn và hiển thị nó trên màn hình chính. Không cài đặt gì cả.",
"fpkg.image.folderOnly": "Chỉ thư mục game trên máy tính này mới có thể thành ảnh đĩa game.",
"fpkg.image.folderOnly_v2": "Chỉ thư mục game (trên máy này, máy chủ đã lưu hoặc PS5) mới có thể trở thành ảnh game.",
"fpkg.image.folderOnly_v4": "Chỉ thư mục game, image game hoặc tệp nén (.zip, .7z, .rar) có chứa game mới có thể thành image game; tệp nén sẽ được giải nén vào thư mục đầu ra trước.",
"fpkg.card.make": "② Tạo gì",
"fpkg.card.options_v2": "③ Tùy chọn",
"fpkg.card.run_v2": "④ Tạo và cài đặt",
