"fpkg.make.pkg_title": "Một gói (.pkg)",
"fpkg.make.pkg_body": "Cài lên PS5 như game từ cửa hàng, stream từ đây hoặc tải lên trước. Game PS4 chạy trên mọi firmware; game PS5 từ 11.60 trở xuống.",
"fpkg.make.image_title": "Một ảnh game",
"fpkg.make.image_body": "Một tệp trên ổ PS5 mà ShadowMount+ gắn và hiển thị ở màn hình chính. Không cài gì cả, và chạy trên firmware mà gói PS5 không chạy được.",
"fpkg.make.recommended": "Nên chọn",
"fpkg.make.recommended_fw": "Nên chọn trên FW {fw}",
"fpkg.make.pick_game": "Kiểm tra một game ở ①, lựa chọn phù hợp hơn cho PS5 của bạn sẽ được đánh dấu.",
"fpkg.make.why_image": "Game PS5 này cài được dạng gói nhưng không chạy trên FW {fw}; dạng ảnh thì chạy.",
"fpkg.make.why_pkg": "Gói là lựa chọn thông thường: cài và chạy như mọi game khác.",
"fpkg.run.summary": "Tạo {what} của {title} trong {dir}.",
