connection_payload_engine_unreachable: "Ứng dụng không kết nối được tới engine của chính nó trên máy tính này, nên không biết trình trợ giúp đã khởi động trên PS5 hay chưa. Đây không phải lỗi của PS5: thông báo ở đầu cửa sổ cho biết lý do và có thể khởi động lại engine. Sau đó nhấn Gửi trình trợ giúp lần nữa. ({error})",
"engine_problem.missing.fix": "Khôi phục ps5upload-engine từ vùng cách ly của phần mềm diệt virus (hoặc cho phép nó), hoặc cài lại ứng dụng.",
"engine_problem.missing.why": "Chương trình engine bị thiếu trong thư mục ứng dụng. Phần mềm bảo mật đôi khi cách ly nó.",
"engine_problem.port.fix": "Nhấn Khởi động lại engine. Nếu không được, hãy cho phép ps5upload-engine trong tường lửa hoặc phần mềm diệt virus, rồi khởi động lại ứng dụng.",
"engine_problem.port.why": "Có thứ gì đó đang giữ địa chỉ của engine ({url}) nhưng không phản hồi: một chương trình khác trên cổng đó, hoặc phần mềm bảo mật chặn kết nối tới nó.",
"engine_problem.proxy.fix": "Tắt proxy hoặc công cụ VPN cho địa chỉ cục bộ (127.0.0.1), hoặc khởi động ứng dụng không có thiết lập http_proxy / ALL_PROXY.",
"engine_problem.proxy.why": "Yêu cầu gửi tới engine đã đi tới một proxy được đặt trên máy tính này thay vì tới engine.",
"engine_problem.remote.fix": "Kiểm tra engine (container Docker hoặc máy tính khác) đang chạy và truy cập được tại địa chỉ đó, hoặc đổi địa chỉ trong Cài đặt.",
"engine_problem.remote.why": "Engine mà ứng dụng này được đặt để dùng ({url}) không phản hồi.",
"engine_problem.restart": "Khởi động lại engine",
"engine_problem.slow.fix": "Nhấn Khởi động lại engine. Tường lửa hoặc phần mềm diệt virus lọc kết nối cục bộ cũng có thể gây ra điều này: hãy cho phép ps5upload-engine.",
"engine_problem.slow.why": "Engine đang chạy nhưng không phản hồi.",
"engine_problem.stopped.fix": "Nhấn Khởi động lại engine. Nếu nó lại dừng, màn hình Nhật ký cho biết lý do.",
"engine_problem.stopped.why": "Engine không chạy: nó đã dừng, hoặc chưa từng khởi động.",
"engine_problem.title": "Ứng dụng không kết nối được tới engine trên máy tính này",
"engine_problem.web.fix": "Kiểm tra máy chủ (container Docker) đang chạy, rồi tải lại trang này.",
"engine_problem.web.why": "Trang này đã mất kết nối tới máy chủ ps5upload đã cung cấp nó.",
gate_engine_down_body_v2: "Màn hình này cần engine của ứng dụng, nhưng engine không phản hồi. Thông báo ở đầu cửa sổ cho biết lý do và có thể khởi động lại nó.",
"profile.np.body": "Khiến PS5 coi tài khoản đang đăng nhập là đã đăng nhập PlayStation Network, không cần liên hệ Sony. Một số tính năng của máy chỉ mở cho tài khoản đã đăng nhập, trong đó có Remote Play. Dùng np-fake-signin của earthonion, được tải từ trang dự án khi bạn nhấn nút.",
"profile.np.confirm_title": "Đăng nhập cho tài khoản này?",
