"profile.np.sent": "np-fake-signin {version} đã chạy trên PS5. Khởi động lại PS5 để hoàn tất; sau đó tài khoản hiện là đã đăng nhập, và có thể bật Cài đặt > Hệ thống > Remote Play.",
"profile.np.sign_in": "Đăng nhập",
"profile.np.state_loading": "Đang đọc tài khoản…",
