"profile.np.state_no_user": "Chưa có người dùng nào đăng nhập trên PS5. Hãy đăng nhập hồ sơ bạn muốn rồi quay lại.",
"profile.np.state_not_activated": "{user} (tài khoản {slot}) chưa có ID tài khoản. Hãy kích hoạt nó trước trong mục Tài khoản ở trên.",
"profile.np.state_ready": "Sẵn sàng: {user} (tài khoản {slot}) đã được kích hoạt.",
"profile.np.step_activate": "Tài khoản cần có ID tài khoản. Tài khoản liên kết PSN đã có; nếu không, hãy kích hoạt nó trong mục Tài khoản ở trên (kích hoạt ngoại tuyến).",
