"pkg.sony_80b21104": "PS5 không nhận gói này (0x80B21104). Nếu các gói khác vẫn cài được trên máy này thì vấn đề nằm ở tệp này: thường là gói của một trò chơi mới, được tạo bằng công cụ mới hơn mức firmware của máy này hiểu, hoặc gói không phải bản ký giả (FPKG). Hãy dùng gói làm cho firmware của bạn (bản backport), hoặc cài trò chơi theo cách không qua trình cài: sao chép thư mục trò chơi, hoặc tệp ảnh trò chơi (.exfat hay .ffpfsc) cho ShadowMount+, bằng Tải lên.",
