sendpayload_probe_invalid_ext: "Payload phải là tệp .elf, .bin, .js, .lua hoặc .jar.",
sendpayload_probe_no_signature: "Không tìm thấy chữ ký PS5Upload — chỉ dùng nếu bạn tin payload này.",
