sendpayload_probe_read_error: "Không đọc được tệp này ({error}). Kiểm tra xem tệp còn tồn tại và mở được không, rồi chọn lại.",
sendpayload_probe_too_small: "Tệp này trống nên không có gì để gửi.",
servers_subtitle: "NAS và máy chủ của bạn (SMB, FTP, FTPS, SFTP/WebDAV). Ở bất cứ đâu bạn duyệt tìm trò chơi hay tệp, hãy chọn từ chúng bằng nút ▾ cạnh Duyệt.",
settings_artwork_cache_explain_v2: "Ảnh bìa trò chơi được lưu ở nơi engine chạy (máy tính này, hoặc máy chủ đối với bản web) để tải tức thì thay vì đọc từ PS5 mỗi lần. Chúng được làm mới tự động, và bị xóa cho một máy khi bạn cài hoặc gỡ một trò chơi trên máy đó.",
settings_backup_downloaded: "Đã tải xuống {name}",
settings_backup_hint_v2: "Gom giao diện, danh sách PS5, lịch sử thông báo, nhật ký hoạt động và các tùy chọn khác vào một tệp JSON, để khôi phục sau khi xóa bộ nhớ ứng dụng hoặc trên máy khác. Không bao gồm ghép đôi máy, Bộ sưu tập, mật khẩu máy chủ đã lưu và thư viện backport.",
settings_backup_restored: "Đã khôi phục {count} cài đặt. Khởi động lại ứng dụng để mọi thay đổi có hiệu lực.",
settings_backup_saved: "Đã lưu vào {path}",
settings_card_console_rest: "Chế độ nghỉ",
settings_card_console_connect: "Kết nối",
auto_bringup_label: "Tự khởi tạo",
auto_bringup_hint: "Khi trình nạp (elfldr, cổng 9021) của một PS5 đã lưu đang chạy và trình trợ giúp chưa chạy, ứng dụng tự chạy Khởi tạo nhanh: danh sách phát khởi tạo của bạn nếu đã đặt, rồi trình trợ giúp, rồi danh sách phát trình nạp tự động. Một lần mỗi khi máy khởi động; sau chế độ nghỉ chỉ gửi lại trình trợ giúp. Ứng dụng chờ khoảng 90 giây sau khi trình nạp xuất hiện để trình nạp tự động của máy chạy xong trước. Mặc định tắt.",
bringup_auto_hint_short: "Tự chạy khi trình nạp của PS5 đang chạy mà trình trợ giúp thì không, khoảng 90 giây sau khi trình nạp xuất hiện. Một lần mỗi khi máy khởi động.",
settings_card_install_fallback: "Khi PS5 không lấy được gói",
settings_card_system_files: "Tệp hệ thống",
settings_file_hint_v2: "Các tùy chọn chính (giao diện, ngôn ngữ, engine, đường dẫn lưu, mặc định tải lên, trợ năng, thanh bên) được sao chép vào tệp JSON này. Bạn có thể sửa thủ công; thay đổi có hiệu lực ở lần mở ứng dụng tiếp theo. Tệp không chứa mọi thứ: dùng Sao lưu / khôi phục để mang theo toàn bộ tùy chọn.",
settings_group_console: "Máy chơi game",
settings_group_fakelibs: "Backport",
settings_group_files_saves: "Tệp & dữ liệu lưu",
settings_group_installs: "Cài đặt gói",
settings_schedule_label_placeholder_v2: "Nhãn (vd. sao lưu dữ liệu lưu)",
settings_updates_browser_note: "Trang web này do engine ps5upload phục vụ và cập nhật cùng engine: kéo Docker image mới (hoặc cập nhật engine trên máy chủ) rồi khởi động lại.",
"show_file_list_hint_v2": "Liệt kê các tệp đang tải lên bên dưới thanh tiến trình. Tắt đi nếu danh sách quá rối với thư mục có hàng nghìn tệp — bạn vẫn thấy tiến trình tổng, tốc độ và thời gian còn lại.",
show_file_list_v2: "Hiện danh sách tệp khi tải lên",
stats_description_v2: "Tổng của các thao tác hiển thị cho máy này. Ứng dụng giữ {count} thao tác gần nhất nên các thao tác cũ hơn không được tính. Tính từ lịch sử cục bộ; không gì rời khỏi máy của bạn.",
status_keep_awake_tooltip_v2: "Giữ thức đang đặt là “Luôn khi đã kết nối” — các máy đã kết nối sẽ không tự vào chế độ nghỉ khi ứng dụng đang mở. Thay đổi trong Cài đặt → Máy chơi game.",
update_idle_v2: "Chưa kiểm tra. Khi bật kiểm tra tự động, ứng dụng kiểm tra ngầm lúc khởi động, tối đa một lần mỗi ngày.",
upload_auto_resume_hint_browser: "Nếu lượt tải lên bị ngắt giữa chừng, tiếp tục từ chỗ dừng khi trình trợ giúp của PS5 phản hồi lại, thử lại vài lần trước khi bỏ cuộc. Trang này không thể tự gửi lại trình trợ giúp: nếu PS5 đã khởi động lại, hãy gửi lại nó trước. Lỗi nghiêm trọng như PS5 hết dung lượng vẫn dừng ngay. Bật theo mặc định.",
upload_wake_for_uploads: "Đánh thức PS5 cho lượt tải lên đang chờ",
upload_wake_for_uploads_hint: "Khi một lượt tải lên đang chờ PS5 ở chế độ nghỉ, gửi tín hiệu đánh thức rồi tiếp tục ngay khi trình trợ giúp chạy lại. Chỉ áp dụng cho máy đã thiết lập đánh thức ở màn hình Kết nối. Bật theo mặc định.",
upload_picker_from_ps5_hint: "Sao chép từ PS5 khác? Chọn tệp trong Hệ thống tệp và chọn Gửi sang máy khác.",
usb_wizard_title_v2: "USB payload",
v5_qa_ready: "Sẵn sàng",
v5_qa_unavailable: "Không khả dụng",
"fpkg.stage.pack": "Đóng gói tài nguyên LZ4",
"fpkg.image.lz4": "Gói tài nguyên AMPR LZ4 (nhỏ hơn, cho ShadowMount+)",
"fpkg.image.lz4_body": "Đóng gói dữ liệu của game vào các gói tài nguyên LZ4 mà chính ampr_emu của game (fakelib/libSceAmpr.sprx) đọc lại, nhờ đó ảnh đĩa nhỏ hơn. Tệp thực thi, tệp hệ thống và phương tiện đã nén sẵn được giữ nguyên. Chỉ dùng với .exfat thường, không nén .ffpfsc.",
"fpkg.image.lz4_unavailable": "Không khả dụng cho game này: {reason}",
"fpkg.image.lz4_needs_runtime": "Đánh dấu “Đưa ampr_emu 0.4.2.1 vào ảnh” ở trên để dùng gói: {reason}",
"fpkg.image.lz4_runtime": "ampr_emu của game: {version}",
"fpkg.image.lz4_profile": "Dùng hồ sơ (.toml)…",
"fpkg.image.lz4_profile_named": "Hồ sơ: {name}",
"fpkg.image.lz4_profile_clear": "Dùng hồ sơ có sẵn",
