"minion_lan_hint": "Tắt: chỉ trình duyệt của chính PS5 mới mở được. Bật: điện thoại, máy tính bảng hoặc máy tính trong cùng mạng cũng mở được, nghĩa là bất kỳ ai trong mạng đó đều mở được. Chỉ bật ở nhà.",
"minion_open_here": "Mở tại đây",
"minion_remove_note": "Gỡ sẽ tắt Minion và xóa những gì nó lưu trên PS5: mục yêu thích và thư mục gần đây của Tệp, bộ nhớ đệm Thư viện game và nhật ký tay cầm. Chia sẻ mạng, cheat và bản sao lưu vẫn còn; ứng dụng trên PC cũng dùng chúng.",
"minion_remove": "Gỡ Minion khỏi PS5 này…",
"minion_remove_title": "Gỡ PS5Upload Minion?",
"minion_remove_confirm": "Ô trên màn hình chính và trang của nó sẽ mất, các tệp riêng của nó trên PS5 sẽ bị xóa. Trình trợ giúp sẽ giữ nó ở trạng thái tắt từ nay. Bạn có thể bật lại tại đây bất cứ lúc nào.",
"minion_remove_go": "Gỡ",
