"fs_dragout_over_cap": "Một lần kéo lấy tối đa 4 GB. Để lấy nhiều hơn, nhấp chuột phải → Tải xuống.",
"fs_drag_hint_move": "Kéo tệp và thư mục ra ngoài cửa sổ để sao chép sang máy tính này, hoặc kéo vào để sao chép vào đây. Giữ Alt (⌥ Option trên Mac) khi kéo để di chuyển chúng vào một thư mục ở đây.",
"fs_drag_hint": "Kéo tệp và thư mục ra ngoài cửa sổ để sao chép sang máy tính này, hoặc kéo vào để sao chép vào đây.",
