"game_search_files": "Tìm trong tệp của game này",
"installed_uninstall_no_copy": "Bộ sưu tập trên máy tính này không có bản sao của game này: hãy lưu gói của nó ở đâu đó trước khi gỡ cài đặt.",
"connection_send_payload_moved": "Muốn gửi payload khác (kstuff, etaHEN, bất kỳ .elf nào)? Mục đó nằm ở Payload → Gửi payload. Màn hình này chỉ gửi trình trợ giúp PS5Upload.",
"connection_send_payload_open": "Mở Gửi payload",
"upload_elf_title": "Đây là payload (.elf), không phải trò chơi",
"upload_elf_body": "Tải lên chỉ sao chép tệp. ShadowMount+ chỉ nhận thư mục trò chơi (có eboot.bin và sce_sys) và ảnh trò chơi, không bao giờ nhận tệp .elf, nên nó sẽ không xuất hiện trên màn hình chính. Để chạy nó, hãy gửi nó tới trình nạp của máy. Thứ nên tải lên là ứng dụng homebrew dạng ảnh .ffpkg hoặc .exfat, hoặc thư mục có eboot.bin.",
"netdoctor.hint.below_test": "Lần tải lên này chạy ở {speed}, thấp hơn nhiều so với {expected} mà bài kiểm tra tốc độ đo được.",
"netdoctor.hint.runs_at": "Lần tải lên này chạy ở {speed}.",
"netdoctor.hint.cause_source": "Thứ kìm nó lại là việc đọc tệp trên máy tính này, không phải mạng: ổ USB hoặc ổ cứng, thư mục mạng (NAS) hay việc giải nén một tệp nén đều chậm hơn đường truyền. Sao chép trò chơi vào SSD trong máy trước, hoặc tải lên các tệp sau khi đã giải nén, sẽ cho tốc độ tối đa.",
"netdoctor.hint.cause_disk": "Thứ kìm nó lại là ổ đĩa của PS5, không phải mạng: ổ USB ngoài, ổ gần đầy hoặc hàng nghìn tệp nhỏ (mỗi tệp tốn thời gian riêng) ghi chậm hơn tốc độ đường truyền mang tới. Ảnh trò chơi (.ffpkg hoặc .exfat) được gửi như một tệp duy nhất.",
"netdoctor.hint.cause_workers": "PS5 vẫn đang ghi những gì nó nhận được, không phải đang chờ mạng. Với nhiều tệp nhỏ, mỗi tệp tốn thời gian riêng; ảnh trò chơi (.ffpkg hoặc .exfat) được gửi như một tệp duy nhất.",
"netdoctor.hint.cause_cap": "Thứ kìm nó lại là giới hạn tốc độ tải lên (khoảng {cap} MiB/s, ở màn hình này và trong Cài đặt). Đặt về 0 để bỏ giới hạn.",
"profile.np.confirm_body_v2": "np-fake-signin ghi các tệp và thiết lập đăng nhập PlayStation Network cho {user} lên PS5. Không gửi gì tới Sony. Sau đó hãy khởi động lại PS5.",
"profile.np.side_effect": "Tác dụng phụ đã biết: sau đó một số máy đòi \"Tạm thời tắt giới hạn máy PS5\" trước khi mở bất kỳ trò chơi nào, và Cài đặt > Người dùng và tài khoản > Khác > Đăng xuất có thể bị mờ. Ứng dụng lưu trước trên PS5 một bản sao của mọi thứ np-fake-signin thay đổi, nên Hoàn tác đăng nhập ở đây sẽ khôi phục lại.",
"profile.np.backing_up": "Đang lưu bản sao thiết lập hiện tại của tài khoản trên PS5…",
"profile.np.backup_failed": "PS5 không lưu được bản sao thiết lập của tài khoản nên np-fake-signin chưa được chạy. Hãy thay trình trợ giúp bằng phiên bản của ứng dụng này rồi thử lại. ({error})",
"profile.np.step_restart_v2": "Khởi động lại PS5. Để hoàn tác sau này, bấm Hoàn tác đăng nhập ở đây rồi khởi động lại.",
"profile.np.undo": "Hoàn tác đăng nhập",
"profile.np.undo_hint": "Bản sao thiết lập của tài khoản này từ trước khi đăng nhập được lưu trên PS5; nút này khôi phục nó.",
"profile.np.undo_confirm_title": "Hoàn tác đăng nhập?",
"profile.np.undo_confirm_body": "Đưa thiết lập và tệp của {user} về như trước khi chạy np-fake-signin. Sau đó hãy khởi động lại PS5. Các tính năng cần tài khoản đã đăng nhập, trong đó có Remote Play, có thể không mở được cho đến khi bạn đăng nhập lại.",
"profile.np.undoing": "Đang khôi phục thiết lập…",
"profile.np.undone": "Đã khôi phục ({count} thiết lập và tệp). Khởi động lại PS5 để hoàn tất.",
"profile.np.no_backup": "Tài khoản này mang thiết lập mẫu của np-fake-signin (ngày sinh 1983-04-12, cờ người lớn ngoại tuyến tắt) và trên PS5 này không có bản sao nào từ trước, nên ứng dụng không thể hoàn tác. Nếu giờ PS5 đòi tạm tắt giới hạn máy trước khi mở trò chơi: Cài đặt > Gia đình và kiểm soát của phụ huynh > Giới hạn máy PS5 (mã 0000 nếu bạn chưa đổi), rồi gỡ giới hạn ở đó.",
"linkdl.lz4_title": "Liên kết này được nén bằng LZ4",
"linkdl.image_title": "Liên kết này là một bản image trò chơi",
"linkdl.lz4_help": "ps5upload có thể giải nén trong khi tải, nên PS5 nhận được tệp đã giải nén. Không có gì được lưu trên máy tính này, và PS5 chỉ cần chỗ cho tệp đã giải nén.",
"linkdl.lz4_unpack": "Giải nén trên đường truyền",
"linkdl.lz4_unpack_hint": "Tắt: tệp .lz4 được lưu nguyên trạng trên PS5.",
"linkdl.image_hint": "Một bản image trò chơi {kind}. ShadowMount+ gắn nó nguyên trạng từ một thư mục mà nó quét, như homebrew trên một ổ. Tệp chỉ xuất hiện ở đó khi đã hoàn tất.",
"pm_add_failed": "Không thể lưu {name} vào Payload Manager",
