"payloads_description_running": "Các chương trình đang chạy trên PS5 lúc này, cùng các cổng đang dùng và thứ thường lắng nghe trên mỗi cổng. Bạn có thể dừng hoặc khởi động lại một chương trình; cẩn thận với tiến trình hệ thống, dừng nhầm có thể làm máy treo.",
