"ps4move_badge": "Thử nghiệm",
"ps4move_experimental": "Thử nghiệm: đưa dữ liệu lưu định dạng PS4 lên PS5 không phải lúc nào cũng được, một trò có thể không tải được. Hãy thử một trò trước; dữ liệu lưu PS5 của nó được giữ lại, có thể đưa lại từ các bản sao lưu của trò.",
"ps4move_safety": "PS4 chỉ được đọc, không bao giờ bị thay đổi. Dữ liệu lưu của nó được chép về máy tính này trước. Trên PS5 chỉ các trò bạn chọn bị động tới, dữ liệu lưu của từng trò được sao lưu trước khi thay, và không gì khác (người dùng, tệp hệ thống, cúp) bị thay đổi.",
"ps4move_need_dir": "Hãy chọn một thư mục trong Sao lưu tự động ở trên trước: dữ liệu lưu của PS4 được giữ ở đó, cùng mỗi dữ liệu lưu PS5 trước khi bị thay.",
