"rp_game_mode_android": "Trong khi chơi, màn hình luôn sáng, thiết bị giữ tốc độ ổn định khi có thể, và TV nối qua HDMI được yêu cầu bật chế độ chơi game.",
"rp_set_controls": "Điều khiển",
"rp_capture_pointer": "Nhấp vào hình sẽ ẩn con trỏ",
"rp_capture_pointer_hint": "Esc để hiện lại.",
"rp_rumble": "Rung tay cầm",
"rp_mic_setting": "Micrô (thử nghiệm)",
"rp_mic_setting_hint": "Thêm nút micrô để trò chuyện bằng giọng nói. Áp dụng từ lần bắt đầu tiếp theo.",
"rp_touch_controls": "Tay cầm trên màn hình",
"rp_touch_auto": "Trên màn hình cảm ứng",
"rp_touch_on": "Luôn luôn",
"rp_touch_off": "Không bao giờ",
"rp_controls_hint": "Tay cầm cũng dùng được: cắm vào hoặc ghép nối với thiết bị này. Shift + kéo trên hình là ngón tay trên touchpad.",
"rp_hid_touchpad": "Dùng bàn cảm ứng của DualSense",
"rp_hid_touchpad_hint": "Trình duyệt sẽ hỏi tay cầm nào: hãy chọn DualSense.",
"rp_hid_touchpad_on": "Bàn cảm ứng DualSense đang được đọc trong trình duyệt này.",
"rp_settings": "Cài đặt",
"rp_running_elsewhere": "Chơi đang chạy trên {name}",
"rp_show_here": "Hiện ở đây",
"rp_running_elsewhere_body": "Nó được bắt đầu từ cửa sổ khác hoặc trước khi tải lại trang này, và vẫn đang chạy.",
"rpg_user_title": "Đăng nhập một người dùng trên PS5",
"rpg_user_body": "Trên máy, chọn người dùng bạn sẽ chơi. Không cần ai ở lại màn hình, nhưng người dùng phải đang đăng nhập. Hãy dùng người dùng không có mã đăng nhập: mã đăng nhập sẽ chặn việc tự động đăng nhập khi máy thức dậy.",
"rpg_account_title": "Cấp ID tài khoản cho người dùng đó",
"rpg_account_body": "Remote Play ghép nối với một ID tài khoản. Người dùng liên kết với PlayStation Network đã có sẵn; người dùng ngoại tuyến cần đặt một ID trong «Người dùng» ở trên (ID nào cũng được; hãy ghi lại, các bản lưu tạo sau đó sẽ gắn với ID này).",
"rpg_signin_title": "Đăng nhập tài khoản vào PlayStation Network (ngoại tuyến)",
"rpg_signin_body": "PS5 chỉ cho tài khoản đã đăng nhập dùng Remote Play. Nếu cài đặt Remote Play của chính máy bị mờ, hãy chạy đăng nhập ngoại tuyến bên dưới (không gửi gì tới Sony), rồi khởi động lại PS5. Có thể hoàn tác.",
"rpg_signin_fix": "Tới phần đăng nhập",
"rpg_service_title": "Bật Remote Play",
"rpg_service_body": "Cài đặt › Hệ thống › Remote Play › Bật Remote Play. Ứng dụng có thể bật giúp bạn, và trên firmware 10.00 trở lên còn cho phép cả người dùng này.",
"rpg_rest_title": "Cho phép bật PS5 từ chế độ nghỉ",
"rpg_rest_body": "Cài đặt › Hệ thống › Tiết kiệm điện › Tính năng khả dụng ở chế độ nghỉ: bật «Luôn kết nối Internet» và «Cho phép bật PS5 từ mạng». Nếu thiếu, máy ở chế độ nghỉ không thể được bật và mạng của nó sẽ ngủ sau vài giây. Chỉ máy mới hiển thị các mục này.",
"rpg_pair_title": "Ghép nối ứng dụng này với máy",
"rpg_pair_body": "Kết nối › Bật & đăng nhập › Thiết lập. Một cú nhấp đăng ký ứng dụng này với PS5 (giống ghép nối ứng dụng PS Remote Play) và giữ khóa trên máy tính này. Phát trực tuyến, bật máy và đăng nhập đều dùng các khóa đó; hãy làm lại sau khi đặt lại máy hoặc đổi người dùng.",
"rpg_play_title": "Chơi",
"rpg_play_body": "Mở «Remote Play» và nhấn «Bắt đầu»: ứng dụng bật máy nếu đang nghỉ, đăng nhập và phát trực tuyến. Chơi bằng tay cầm kết nối với máy tính này, bàn phím hoặc cảm ứng. Để dùng ứng dụng PS Remote Play của Sony hoặc chiaki-ng thay thế, hãy yêu cầu mã PIN bên dưới và nhập vào đó.",
"rpg_play_fix": "Mở Remote Play",
"rpg_title": "Thiết lập Remote Play",
"rpg_progress": "Đã xong {done}/{n} bước được kiểm tra",
"rpg_on_console": "kiểm tra trên máy",
"rpg_trouble": "Nếu vẫn không được",
"rpg_t_start_q": "Nút Bắt đầu bị mờ trên màn hình Chơi.",
"rpg_t_start_a": "Ứng dụng này chưa ghép nối với máy đó: hãy làm bước 6 (Kết nối › Bật & đăng nhập › Thiết lập).",
"rpg_t_pair_q": "Khi thiết lập ghép nối, báo không có người dùng đã đăng nhập với tài khoản đã kích hoạt.",
"rpg_t_pair_a": "Bước 1 và 2: đăng nhập một người dùng trên PS5 và cấp cho họ ID tài khoản, rồi thử lại.",
"rpg_t_grey_q": "Cài đặt Remote Play của chính PS5 bị mờ.",
"rpg_t_grey_a": "Tài khoản chưa đăng nhập PlayStation Network. Hãy chạy đăng nhập ngoại tuyến (bước 3) và khởi động lại PS5.",
"rpg_t_wake_q": "Máy không thức dậy, hoặc thức dậy nhưng dừng ở màn hình chọn người dùng.",
"rpg_t_wake_a": "Kiểm tra bước 5 trên máy. Người dùng có mã đăng nhập sẽ chặn việc tự động đăng nhập. Nếu máy đã được đặt lại hoặc đổi người dùng, hãy thiết lập ghép nối lại (bước 6).",
"rpg_t_black_q": "Hình vẫn đen, giật, hoặc âm thanh rè.",
"rpg_t_black_a": "Dùng kết nối có dây hoặc Wi-Fi 5 GHz cho PS5 và máy tính này, và thử 720p hoặc 30 fps trong cài đặt Remote Play. Tường lửa trên máy tính này phải cho phép ứng dụng trên mạng cục bộ (Remote Play dùng cổng TCP và UDP 9295–9304). Trong trình duyệt, hãy dùng Chrome, Edge hoặc Safari mới: hình ảnh cần WebCodecs.",
"rpg_t_busy_q": "Báo PS5 vẫn đang kết thúc phiên trước, hoặc một máy khác đang phát.",
"rpg_t_busy_a": "Mỗi lần chỉ một máy phát, và PS5 cần tới 30 giây sau khi phiên kết thúc. Dừng luồng kia, chờ một chút, rồi nhấn «Bắt đầu» lại.",
"rpg_t_restrict_q": "Sau khi đăng nhập ngoại tuyến, trò chơi đòi tắt giới hạn máy.",
"rpg_t_restrict_a": "Dùng «Hoàn tác đăng nhập» trên trang này rồi khởi động lại, hoặc gỡ giới hạn trong Cài đặt › Gia đình và kiểm soát của phụ huynh › Giới hạn máy PS5 (mã 0000 nếu bạn chưa đổi).",
