"mesh_rp_started": "{name} đã bắt đầu chơi trên máy này",
"rp_keys_body3": "Bấm vào hình để chơi bằng bàn phím; Esc trả lại con trỏ. Bấm đúp để toàn màn hình; ở đó nhấn nhanh Esc là nút Tròn, giữ Esc để thoát toàn màn hình. Phím, âm thanh và hơn nữa trong Cài đặt.",
