"dump_decrypt_risk": "Giải mã có thể làm treo máy",
"dump_decrypt_risk_body": "Để giải mã, trình trợ giúp tạm thay một phần hệ thống mà mọi chương trình dùng cho từng tệp thực thi. Nếu game đọc tệp đúng lúc đó, máy có thể bị treo và phải tắt nguồn cứng. Hãy ở màn hình khởi đầu của game trong lúc chạy. Chỉ firmware đến 13.60; trên firmware mới hơn bản dump là bản sao thường.",
